programs.gitlog:
package changelog

import "strings"

func lokiCases() {
	// change: the issue's own example, and neighbouring ranges that also must keep merge subjects
	lokiCase("c1", "change", "CommitsCmd v1.2.0..HEAD (issue example)", func() any {
		return strings.Join(CommitsCmd("v1.2.0", "HEAD"), " ")
	})
	lokiCase("c2", "change", "CommitsCmd v1.1.0..v1.2.0", func() any {
		return strings.Join(CommitsCmd("v1.1.0", "v1.2.0"), " ")
	})
	lokiCase("c3", "change", "CommitsCmd v1.0.0..HEAD", func() any {
		return strings.Join(CommitsCmd("v1.0.0", "HEAD"), " ")
	})

	// keep: shared helpers, sibling commands, and formatting that the fix must not alter
	lokiCase("k1", "keep", "AuthorsCmd v1.2.0..HEAD (issue example values)", func() any {
		return strings.Join(AuthorsCmd("v1.2.0", "HEAD"), " ")
	})
	lokiCase("k2", "keep", "AuthorsCmd empty from ref", func() any {
		return strings.Join(AuthorsCmd("", "HEAD"), " ")
	})
	lokiCase("k3", "keep", "logArgs with subject format", func() any {
		return strings.Join(logArgs("%s"), " ")
	})
	lokiCase("k4", "keep", "logArgs with author format", func() any {
		return strings.Join(logArgs("%an <%ae>"), " ")
	})
	lokiCase("k5", "keep", "LastTagCmd", func() any {
		return strings.Join(LastTagCmd(), " ")
	})
	lokiCase("k6", "keep", "Render with merge subject from issue", func() any {
		return Render("v1.2.0", []string{"Merge pull request #41 from team/export"})
	})
	lokiCase("k7", "keep", "Render with nil subjects", func() any {
		return Render("v1.2.0", nil)
	})
	lokiCase("k8", "keep", "Render trims whitespace and skips blanks", func() any {
		return Render("v1.2.0", []string{"  Add export  ", "", "  "})
	})
	lokiCase("k9", "keep", "Render with empty version", func() any {
		return Render("", []string{"x"})
	})
	lokiCase("k10", "keep", "Contributors case and whitespace variants", func() any {
		return Contributors([]string{"bo <bo@x.io>", "BO <bo@x.io>", " bo <bo@x.io> "})
	})
	lokiCase("k11", "keep", "Contributors sorts and dedupes", func() any {
		return Contributors([]string{"zed <z@x.io>", "al <al@x.io>", "zed <z@x.io>"})
	})
	lokiCase("k12", "keep", "Contributors nil input", func() any {
		return Contributors(nil)
	})
}

programs.flagusage:
package flags

func lokiCases() {
	// change cases
	lokiCase("c1", "change", "FlagLine issue example: long and short names", func() any {
		return FlagLine(Flag{Name: "output", Short: "o", Usage: "write to file"})
	})
	lokiCase("c2", "change", "Help listing for the issue example flag with a short alias", func() any {
		return Help("tool", []Flag{{Name: "output", Short: "o", Usage: "write to file"}})
	})
	lokiCase("c3", "change", "FlagLine issue example with a default and a short alias", func() any {
		return FlagLine(Flag{Name: "output", Short: "o", Usage: "write to file", Default: "out.txt"})
	})

	// keep cases
	lokiCase("k1", "keep", "[s1] FlagLine of a no-short flag with a default value", func() any {
		return FlagLine(Flag{Name: "verbose", Usage: "print more", Default: "false"})
	})
	lokiCase("k2", "keep", "[s2] Help header for a single no-short flag named verbose", func() any {
		return Help("tool", []Flag{{Name: "verbose", Usage: "print more"}})
	})
	lokiCase("k3", "keep", "[s3] MissingError for a required no-short flag named verbose", func() any {
		return MissingError(Flag{Name: "verbose", Required: true})
	})
	lokiCase("k4", "keep", "FlagLine issue example flag without a short alias, the verbose example", func() any {
		return FlagLine(Flag{Name: "verbose", Usage: "print more"})
	})
	lokiCase("k5", "keep", "Help with no-short flags given out of order, sorted by name", func() any {
		return Help("tool", []Flag{{Name: "verbose", Usage: "print more"}, {Name: "alpha", Usage: "first"}})
	})
	lokiCase("k6", "keep", "Help with empty program name and no flags", func() any {
		return Help("", nil)
	})
	lokiCase("k7", "keep", "Lookup issue example flag by short name -o", func() any {
		fs := []Flag{{Name: "output", Short: "o"}}
		return lokiAll(Lookup(fs, "-o"))
	})
	lokiCase("k8", "keep", "Lookup unknown flag --nope returns the unknown flag error", func() any {
		fs := []Flag{{Name: "output", Short: "o"}}
		return lokiAll(Lookup(fs, "--nope"))
	})
	lokiCase("k9", "keep", "MissingError for a required no-short flag with uppercase name Verbose", func() any {
		return MissingError(Flag{Name: "Verbose", Required: true})
	})
	lokiCase("k10", "keep", "FlagLine no-short flag with surrounding whitespace in usage text", func() any {
		return FlagLine(Flag{Name: "verbose", Usage: "  print more  "})
	})
}
